# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Open VSCode"
# MISE hide=true
# MISE tools={uv="latest", python="3.14"}

# USAGE arg "<folder>" default="." help="Folder to open in VSCode"

import os
import shutil
import subprocess
import sys


def user_env():
  """The environment of the user for the tool: without VIRTUAL_ENV and
  without the bin folder of the script environment on PATH, which uv run
  adds."""
  env = dict(os.environ)
  env.pop("VIRTUAL_ENV", None)
  script_bin = os.path.normpath(os.path.join(sys.prefix, "bin"))
  path = env.get("PATH", "").split(os.pathsep)
  env["PATH"] = os.pathsep.join(p for p in path if os.path.normpath(p) != script_bin)
  return env


def main():
  if not shutil.which("code"):
    print("VSCode is not installed or not in PATH.", flush=True)
    sys.exit(1)
  folder = os.environ.get("usage_folder", "") or "."
  rc = subprocess.run(
    ["code", f"{os.environ.get('MISE_ORIGINAL_CWD', '')}/{folder}"], check=False, env=user_env()
  ).returncode
  sys.exit(128 - rc if rc < 0 else rc)


if __name__ == "__main__":
  main()
